function leaders(){const list=rankFilter==='Friends'?rankings.filter((_,i)=>[0,2,3,6].includes(i)):rankings;return `<div class="tablewrap"><table><thead><tr><th>Rank</th><th>Learner</th><th>Return</th></tr></thead><tbody>${list.map(r=>`<tr><td>#${rankings.indexOf(r)+1}</td><td><div class="flex"><span class="avatar">${r.name==='You'?esc(initials()):r.initials}</span><div><strong>${r.name==='You'?esc(state.name)+' · you':r.name}</strong><p class="small">${r.tier} · ${fmt(r.xp)} XP</p></div></div></td><td class="positive">+${r.ret.toFixed(1)}%</td></tr>`).join('')}</tbody></table></div>`}
function donut(){return `<div class="donut sync-donut" role="img" aria-label="IT Services 32%, Banking 26%, Energy 18%, Auto 14%, FMCG 10%"><div class="donutlabel"><strong>5</strong><span class="small">sectors</span></div></div><div class="sector-legend">${[['IT Services',32],['Banking',26],['Energy',18],['Auto',14],['FMCG',10]].map(([n,v],i)=>`<div><span><i style="background:${['#35d39b','#439bf2','#aa8bef','#e9b76a','#ec829e'][i]}"></i>${n}</span><strong>${v}%</strong></div>`).join('')}</div>`}
function dashboard(){if(account)return serverPerformance.page();return shell('dashboard',`${pagehead('Your investing journey',`Hi, ${esc(state.name.split(' ')[0])} 👋`,'Three contests running. Your AI report for Dividend Derby is ready.','<span class="pill gold">17-day streak</span>')}<div class="home-overview"><section class="panel performance-hero"><span class="small">Overall performance</span><div class="performance-main"><div><div class="hero-return">+12.84<span>%</span></div><p class="positive">▲ 2.31% since last week</p></div><div class="iq-ring" style="--progress:78%"><div><strong>78</strong><span>IQ score</span></div></div></div><div class="performance-details">${metric('Virtual value','₹22,78,160')}${metric('Global rank','#148')}${metric('Benchmark','+4.2% ahead','positive')}</div>${chart()}</section><div class="home-summary"><section class="panel"><span class="summary-icon">${icon('trophy')}</span><p>CONTESTS JOINED</p><div class="num">${14+(state.customContests||[]).length}</div>${link('View my contests →','my-contests','ghost')}</section><section class="panel"><span class="summary-icon blue">${icon('trophy')}</span><p>CONTESTS WON</p><div class="num">3</div><span class="positive small">▲ 50.00%</span></section></div></div><div class="section-heading"><h2>Quick actions</h2></div><div class="quick-actions">${[['contests','trophy','Join Contest'],['contests/create','users','Create Contest'],['portfolio','wallet','Portfolio'],['leaderboard','chart','Leaderboard']].map(([r,i,n])=>link(icon(i)+n+icon('arrow'),r,'secondary')).join('')}</div><div class="section-heading"><h2>Your active contests</h2>${link('View all →','my-contests','ghost')}</div>${activeCards()}<div class="home-lower"><div><section class="panel continue-card"><span class="featureicon">${icon('book')}</span><div><span class="eyebrow">Continue learning</span><h3>Reading a Balance Sheet</h3><p>${courseDone(referenceCourses[1])} of 10 lessons · ${courseDone(referenceCourses[1])*10}%</p><p>Turn an annual report into three numbers that actually matter.</p></div>${link('Resume · 6 min','academy')}</section><section class="panel" style="margin-top:22px"><div class="row"><h3>AI insights</h3><span class="small">From your last three contests</span></div><div class="insight-row"><span class="summary-icon">${icon('check')}</span><div><strong>You diversified well</strong><p>Five sectors with no single position above 18% in the sample report.</p></div></div><div class="insight-row"><span class="summary-icon amber">${icon('shield')}</span><div><strong>You sold Infosys too early</strong><p>Review the sample exit timing and compare it with the original thesis.</p></div></div>${link('Open full report →','insights','ghost full')}</section></div><aside><section class="panel"><div class="row"><h3>Sector allocation</h3><span class="pill">Diversified</span></div>${donut()}</section><section class="panel" style="margin-top:22px"><h3>Rewards Store</h3><div class="num" style="margin-top:15px">${fmt(coins())}</div><p>InvestIQ Coins</p><div class="row small"><span>Progress to Platinum</span><span>${Math.min(100,Math.round((coins()-7500)/7500*100))}%</span></div>${progress((coins()-7500)/75)}<div class="settingsrow"><strong>🛒 Amazon ₹500</strong><span class="small">5,000 coins</span></div>${link('Open Rewards Store →','marketplace','ghost full')}</section></aside></div><div class="section-heading"><h2>Community highlights</h2>${link('Open community →','social','ghost')}</div><section class="panel"><p>Explore discussions and learning reflections in the community.</p>${link('Browse community','social','secondary')}</section>${fixtureNote()}`)}
function contestCard(c){return `<article class="panel contestcard"><div class="row"><span class="contest-symbol">${icon('trophy')}</span><span class="pill ${c.level==='Advanced'?'neutral':''}">${esc(c.level)}</span></div><h3>${esc(c.name)}</h3><span class="small">Hosted by ${esc(c.host)}</span><p>${esc(c.desc)}</p><div class="contest-info">${metric('Prize pool',c.prize)}${metric('Capital',money(c.capital))}${metric('Entry',c.level==='Friends'?'Invite':'Free','positive')}</div><div class="row"><span class="small">${fmt(c.count)} joined</span><span class="small">${c.time} left</span></div>${progress(c.progress)}<div class="row">${link('View contest →','contests/'+c.id)}<button class="ghost" data-sync="build-for" data-id="${c.id}">Build portfolio</button></div></article>`}
function contestPage(id){return serverContests.page(id);}
const allocationTotal=()=>Object.values(state.allocations).reduce((a,b)=>a+Number(b),0);
function stockRows(){
  if(marketState.loading||!marketState.loaded)return '<p class="empty" role="status">Loading instruments and quoted prices…</p>';
  if(marketState.error)return `<div class="empty" role="status"><p>${esc(marketState.error)}</p><button class="secondary" data-action="reload-market">Retry market data</button></div>`;
  if(marketState.pageError)return `<div class="empty" role="status"><p>${esc(marketState.pageError)}</p><button class="secondary" data-action="reload-market">Retry market data</button></div>`;
  if(marketState.pageLoading)return '<p class="empty" role="status">Searching instruments…</p>';
  return marketState.items.map(x=>`<div class="stockrow" data-instrument-id="${x.instrumentId}"><div class="flex"><span class="stockbadge">${esc(x.id.slice(0,2))}</span><div><strong>${esc(x.name)}</strong><p>${esc(x.id)} · ${esc(x.sector)} · ${esc(x.cap)}</p><p class="small">${esc(x.quote?.freshness||'missing')} · ${esc(x.quote?.session_date||'No price')} · synthetic fixture</p></div></div><div class="stock-price">${formatMarketPrice(x.price)}<button class="${x.id in state.allocations?'secondary':'primary'}" data-action="add-stock" data-id="${esc(x.id)}" ${!x.usable||(Object.keys(state.allocations).length>=12&&!(x.id in state.allocations))?'disabled':''}>${x.id in state.allocations?'Added':'Add'}</button></div></div>`).join('')||'<p class="empty">No instruments match.</p>';
}
function portfolio(id){if(account||id)return serverPortfolio.page(id);const c=selectedCompetition(),total=allocationTotal(),count=Object.keys(state.allocations).length;return shell('portfolio',`${pagehead('Step 1 of 2','Select your stocks',`${esc(c.name)} · ${money(c.capital)} virtual capital · 5 to 12 holdings.`)}<div class="builder-steps"><span class="selected"><b>1</b>Select stocks</span><i></i><span><b>2</b>Review & submit</span></div><div class="builder"><section class="panel">${marketNotice()}<div class="grid2"><label class="field">SEARCH<input id="stocksearch" value="${esc(stockQuery)}" placeholder="Search name or symbol" ${marketState.loading?'disabled':''}></label><label class="field">SECTOR<select id="sector-select"><option value="All">All sectors</option>${marketState.sectors.map(x=>`<option value="${x.id}" ${sector===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><div class="tabs" style="margin-top:20px">${['All','Large Cap','Mid Cap','Small Cap'].map(x=>`<button data-sync="cap-filter" data-value="${x}" class="${capFilter===x?'active':''}">${x}</button>`).join('')}</div><div id="stockrows">${stockRows()}</div><div id="market-more">${marketMore()}</div></section><section class="portfolio-draft"><div class="row"><h2>Your portfolio</h2><span class="pill neutral">${count} / 12</span></div><div class="tabs" style="margin-top:20px">${['Quantity','Weight %'].map(x=>`<button data-sync="portfolio-mode" data-value="${x}" class="${portfolioMode===x?'active':''}">${x}</button>`).join('')}</div><div class="row small"><span>Capital deployed</span><span id="deployed-value">${money(total/100*c.capital)} / ${money(c.capital)}</span></div><div class="progress"><span id="deployed-bar" style="width:${Math.min(100,total)}%"></span></div><div id="allocations">${Object.entries(state.allocations).map(([id,v])=>{const x=stocks.find(x=>x.id===id);if(!x)return `<div class="allocation"><strong>${esc(id)}</strong><span class="small">Instrument unavailable; allocation kept in this preview.</span><button class="ghost" data-action="remove-stock" data-id="${esc(id)}">Remove</button></div>`;return `<div class="allocation"><span class="stockbadge">${id.slice(0,2)}</span><div class="allocname"><strong>${id}</strong><p class="small">${x.sector}</p></div>${portfolioMode==='Weight %'?`<input type="number" min="0" max="25" step="0.1" value="${v}" data-alloc="${id}" aria-label="${x.name} weight"><span>%</span>`:`<input type="number" min="0" value="${x.usable?Math.floor(Number(v)/100*c.capital/Number(x.price)):''}" ${!x.usable||marketState.loading?'disabled':''} data-quantity="${id}" aria-label="${x.name} quantity"><span class="small">shares</span>`}<button class="ghost" data-action="remove-stock" data-id="${id}" aria-label="Remove ${x.name}">${icon('close')}</button></div>`}).join('')||'<div class="empty"><span class="featureicon">'+icon('wallet')+'</span><p>Add at least five stocks to continue.</p></div>'}</div><div class="builderfooter"><strong id="allocationstatus" class="${Math.abs(total-100)<.02?'positive':'subtle'}">${total.toFixed(1)}% allocated · max 25% per holding</strong><button class="primary full" data-sync="review-portfolio" ${count<5?'disabled':''}>${count<5?'Add '+(5-count)+' more':'Review & submit →'}</button></div>${state.savedPortfolio?'<div class="callout"><strong>Practice portfolio saved</strong><p>Changes remain a draft until submitted again.</p></div>':''}</section></div>${fixtureNote()}`)}
courses.push({id:'balance-sheet',title:'Reading a Balance Sheet',mins:6,body:['A balance sheet shows assets, liabilities and equity at a point in time. Assets equal liabilities plus equity.','Compare debt, cash and working capital across periods. A single ratio needs business context.'],q:'Which relationship defines a balance sheet?',options:['Assets = liabilities + equity','Revenue = cash','Debt = profit'],correct:0},{id:'valuation',title:'Valuation Without Jargon',mins:5,body:['Price-to-earnings compares the share price with earnings per share. It is a starting point for analysis, not a verdict.','Compare growth, earnings quality, debt and business risk before interpreting a multiple.'],q:'A P/E ratio should be interpreted with:',options:['Business context and earnings quality','No other information','A guaranteed return'],correct:0});

