function demoAcademy(id){if(id)return lessonPage(id);const first=referenceCourses[0];return shell('academy',`${pagehead('Learn','Build the judgement first','Four-minute lessons and quick quizzes. Keep your streak alive to multiply XP.','<span class="pill gold">17-day streak</span>')}<section class="banner learning-hero"><div><span class="eyebrow">Continue learning</span><h2>${first.title}</h2><p>${first.desc}</p><p>Lesson ${Math.min(first.lessons,courseDone(first)+1)} of ${first.lessons} · ${Math.round(courseDone(first)/first.lessons*100)}%</p>${progress(courseDone(first)/first.lessons*100)}${link('Resume · 4 min','academy/'+first.id)}</div><div class="iq-ring" style="--progress:75%"><div><strong>${xpTotal()}</strong><span>Total XP</span></div></div></section><div class="section-heading"><h2>Courses</h2></div><div class="course-grid">${referenceCourses.map(c=>`<article class="panel course"><div class="row"><span class="featureicon">${icon('book')}</span><span class="pill neutral">${c.level}</span></div><h3>${c.title}</h3><span class="small">${c.lessons} lessons · ${c.mins} min each</span><p>${c.desc}</p><div class="row small"><span>${courseDone(c)} / ${c.lessons} done</span><span>${Math.round(courseDone(c)/c.lessons*100)}%</span></div>${progress(courseDone(c)/c.lessons*100)}${link(courseDone(c)===c.lessons?'Review course':courseDone(c)?'Continue':'Start course','academy/'+c.id,'primary full')}</article>`).join('')}</div><div class="section-heading"><h2>Quizzes</h2></div><div class="grid3">${[['Risk & Diversification',8,120,'diversification','Start quiz'],['Market Cap Basics',6,80,'essentials','Try again'],['Sector Cycles',10,150,'thesis','Complete course to unlock']].map(([n,q,x,id,t],i)=>`<section class="panel"><h3>${n}</h3><p class="small" style="margin:12px 0 22px">${q} questions · ${x} XP</p>${i===2?'<button class="secondary full" disabled>'+t+'</button>':link(t,'academy/'+id,'secondary full')}</section>`).join('')}</div><div class="section-heading"><h2>Achievements</h2></div>${badgeGrid()}<section class="banner"><div><h3>Keep your streak alive</h3><p>One lesson today keeps your 17-day streak and your 1.5× XP multiplier.</p></div>${link('Back to home →','dashboard')}</section>${fixtureNote()}`)}
function lessonPage(id){if(id){const c=courses.find(x=>x.id===id);if(!c)return notFound();return shell('academy',`${pagehead('InvestIQ academy',c.title,`${c.mins} minutes · foundation learning`,link('← All lessons','academy','secondary'))}<div class="lesson"><article class="panel lessonbody"><span class="pill">${state.completed.includes(id)?'Completed':'Your learning journey'}</span>${c.body.map(p=>`<p>${p}</p>`).join('')}<div class="callout"><strong>Your practice task</strong><p>Open your portfolio and write down one thing you would examine before changing its allocation.</p></div></article><section class="panel" style="margin-top:22px"><span class="eyebrow">Check your understanding</span><h3 style="margin-top:13px">${c.q}</h3>${c.options.map((o,i)=>`<button class="quizoption" data-action="quiz" data-index="${i}" aria-pressed="${lessonAnswer===i}">${o}</button>`).join('')}<div id="quizfeedback" aria-live="polite">${lessonAnswer!==null?`<div class="callout ${lessonAnswer===c.correct?'':'red'}"><strong>${lessonAnswer===c.correct?'That’s right.':'Take another look.'}</strong><p>${lessonAnswer===c.correct?'You’ve understood the key idea. Mark this lesson complete.':'Review the lesson and try again.'}</p></div>`:''}</div><div class="row" style="margin-top:20px"><button class="primary" data-action="complete" data-id="${id}" ${lessonAnswer!==c.correct?'disabled':''}>${state.completed.includes(id)?'Lesson completed '+ '✓':'Mark lesson complete'}</button>${link('Put it into practice →','portfolio','secondary')}</div></section></div>`)}return shell('academy',`${pagehead('Learn','InvestIQ Academy','Small lessons. Strong foundations. A little smarter every day.',link(state.completed.length+' / 4 complete','profile','secondary'))}<div class="banner"><div><span class="eyebrow">Your foundation path</span><h3 style="margin-top:10px">Build a confident investing habit.</h3><p>${state.completed.length} of 4 lessons completed · ${state.goal} minute weekly goal</p><div class="progress"><span style="width:${state.completed.length/4*100}%"></span></div></div>${link('Continue learning →','academy/'+(courses.find(c=>!state.completed.includes(c.id))||courses[0]).id)}</div><div class="course-grid">${courses.map((c,i)=>`<article class="panel course"><div class="row"><span class="featureicon">${icon(c.icon)}</span><span class="small">0${i+1} / 04</span></div><span class="pill ${state.completed.includes(c.id)?'':'neutral'}">${state.completed.includes(c.id)?'Completed':'Foundation'} · ${c.mins} min</span><h3>${c.title}</h3><p>${c.desc}</p><div class="row"><span class="small">${state.completed.includes(c.id)?'1 / 1 complete':'0 / 1 complete'}</span><span class="small">${state.completed.includes(c.id)?100:0}%</span></div><div class="progress"><span style="width:${state.completed.includes(c.id)?100:0}%"></span></div>${link(state.completed.includes(c.id)?'Review lesson →':'Start lesson →','academy/'+c.id,'primary full')}</article>`).join('')}</div>`)}
