function demoMarketplace(id){if(id){const r=rewardCatalog.find(r=>r.id===id);if(!r)return notFound();return shell('marketplace',`${pagehead(r.category,r.name,r.desc,link('← Catalog','marketplace','secondary'))}<div class="grid2"><section class="panel reward-detail"><div class="reward-art">${r.emoji}</div><span class="pill">${r.category}</span><h2>${r.name}</h2><p>${r.desc}</p></section><section class="panel"><h2>${fmt(r.cost)} coins</h2><p style="margin:15px 0">Your balance: ${fmt(coins())} InvestIQ Coins</p><p class="small">Local demo redemption only. No reward is shipped, purchased or booked.</p><button class="primary full" style="margin-top:25px" data-sync="redeem" data-id="${r.id}" ${coins()<r.cost||r.id==='trophy'?'disabled':''}>${r.id==='trophy'?'Sold out':coins()<r.cost?'Need more coins':'Preview redemption'}</button></section></div>${fixtureNote()}`)}let list=rewardCatalog.filter(r=>rewardFilter==='All'||r.category===rewardFilter);if(rewardSort!=='Featured')list.sort((a,b)=>rewardSort==='Lowest cost'?a.cost-b.cost:b.cost-a.cost);return shell('marketplace',`${pagehead('Marketplace','Rewards Store','Contests, lessons, quizzes and streaks all pay in InvestIQ Coins. Spend them here.','<button class="secondary" data-sync="earn">How to earn →</button>')}<section class="panel rewards-balance"><div><span class="eyebrow">InvestIQ Coins</span><div class="hero-return">${fmt(coins())}</div><div class="flex"><span class="pill gold">Gold tier</span><span class="small">17-day streak</span></div><div class="row small" style="margin-top:25px"><span>Progress to Platinum</span><span>${Math.min(100,Math.round((coins()-7500)/75))}%</span></div>${progress((coins()-7500)/75)}<p class="small">${fmt(Math.max(0,15000-coins()))} more coins unlocks Platinum: +35% bonus XP.</p></div><div class="grid2 reward-statistics">${[['Lifetime earned','31,250'],['Coins redeemed',fmt(31250-coins())],['Reward tier','Gold'],['Rewards live','38']].map(([n,v])=>`<div><span class="small">${n}</span><strong>${v}</strong></div>`).join('')}</div></section><div class="section-heading"><h2>Catalog</h2><div class="tabs">${['Featured','Lowest cost','Highest cost'].map(x=>`<button data-sync="reward-sort" data-value="${x}" class="${rewardSort===x?'active':''}">${x}</button>`).join('')}</div></div><div class="tabs">${['All',...new Set(rewardCatalog.map(r=>r.category))].map(x=>`<button data-sync="reward-filter" data-value="${x}" class="${rewardFilter===x?'active':''}">${x}</button>`).join('')}</div><div class="reward-grid">${list.map(r=>`<a class="panel reward-card" href="#/marketplace/${r.id}"><div class="reward-art">${r.emoji}</div><div class="row"><span class="small">${r.category}</span>${['hoodie','mousepad','starbucks','resume-review','mock-interview','webinar','beta','dinner','signed-book'].includes(r.id)?'<span class="pill gold">Limited</span>':''}</div><h3>${r.name}</h3><p>${r.desc}</p><div class="row"><strong>${fmt(r.cost)} <span class="small">coins</span></strong><span class="positive small">${r.id==='trophy'?'Sold out':coins()<r.cost?'Need more':'Redeem →'}</span></div></a>`).join('')}</div><div class="section-heading"><h2>Tiers & perks</h2></div><div class="grid4 tiers">${[['Bronze','0 – 2,500','+5% bonus XP · Starter badge'],['Silver','2,500 – 7,500','+10% bonus XP · Weekly quiz packs'],['Gold','7,500 – 15,000','+20% bonus XP · Early contest access'],['Platinum','15,000+','+35% bonus XP · Limited rewards · Premium themes']].map(([n,r,d])=>`<section class="panel"><span class="pill ${n==='Gold'?'gold':'neutral'}">${n}${n==='Gold'?' · Current':''}</span><h3>${r} coins</h3><p>${d}</p></section>`).join('')}</div><div class="section-heading" id="earn-section"><h2>Ways to earn coins</h2></div><div class="grid4 earn-grid">${[['🏆','Win a contest',500],['📚','Complete a learning module',150],['🔥','Daily login',20],['🧠','Daily quiz',50],['👥','Refer a friend',1000],['❤️','Community contribution',100],['🎯','Weekly challenge',300],['🏅','Finish in the top 10',750]].map(([e,n,v])=>`<div class="panel"><span>${e}</span><strong>${n}</strong><span class="positive">+${fmt(v)}</span></div>`).join('')}</div><div class="section-heading"><h2>Redemption history</h2></div><section class="panel">${[...(state.redemptions||[]),{name:'Amazon ₹500',date:'12 Jul 2026',cost:5000,status:'Completed'},{name:'InvestIQ Hoodie',date:'28 Jun 2026',cost:8000,status:'Delivered'},{name:'Premium AI Portfolio Review',date:'19 Jun 2026',cost:4000,status:'Completed'},{name:'Laptop Sleeve',date:'09 Jun 2026',cost:4200,status:'Shipped'},{name:'Webinar with Experts',date:'02 Jun 2026',cost:6500,status:'Pending'}].map(r=>`<div class="settingsrow"><div><strong>${esc(r.name)}</strong><p>${r.date} · illustrative history</p></div><span>−${fmt(r.cost)}</span><span class="pill neutral">${r.status}</span></div>`).join('')}</section><div class="section-heading"><h2>Achievements</h2></div><div class="badge-grid">${[['🎁','First Redemption','Redeemed your first reward'],['🪙','10,000 Coins Earned','Crossed 10k lifetime coins'],['🥇','Gold Collector','Reached the Gold tier'],['🔥','Daily Streak Master','15-day login streak'],['🏆','Contest Champion','Win any public contest'],['📖','Learning Legend','Finish four courses'],['⭐','Community Star','500 likes across your posts']].map(([e,n,d])=>`<div class="panel badge-item"><span style="font-size:27px">${e}</span><strong>${n}</strong><p>${d}</p></div>`).join('')}</div>${fixtureNote()}`)}
