function settings(){const toggle=(id,n,d,on)=>`<div class="settingsrow"><div><strong>${n}</strong><p>${d}</p></div><button class="switch" role="switch" aria-label="${n}" aria-checked="${state.preferences?.[id]??on}" aria-pressed="${state.preferences?.[id]??on}" data-sync="preference" data-id="${id}" data-default="${on}"></button></div>`;return shell('settings',`${pagehead('Preferences','Settings','Control your account, alerts and privacy.')}<section class="panel settings-identity"><div class="flex"><span class="avatar large">${esc(initials())}</span><div><h2>${esc(state.name)}</h2><p>${account?esc(account.email):'Local practice profile'}</p></div></div>${link('View profile →','profile','secondary')}</section><div class="grid2" style="margin-top:23px"><div><section class="panel"><h2>Notifications</h2>${toggle('contest','Contest start & end','Alerts when a contest opens or settles',true)}${toggle('ranks','Rank changes','When you move up or down 10+ places',true)}${toggle('ai','AI insights ready','Weekly performance reports',true)}${toggle('replies','Community replies','Someone answers your post',false)}${toggle('digest','Weekly digest email','A Monday recap of your season',true)}<p class="small" style="margin-top:20px">${account?'Preferences are saved to your account; notification delivery is not connected.':'Preferences are local; notification delivery is not connected.'}</p></section><section class="panel" style="margin-top:23px"><h2>Privacy</h2>${toggle('public','Public profile','Show your display name on visible contest leaderboards and community posts',true)}${toggle('holdings','Portfolio sharing preference','Saved for a future sharing feature; holdings currently stay private',false)}<p class="small" style="margin-top:20px">${account?'Public profile controls author names. Community text remains public; portfolio holdings stay private.':'These switches preview privacy controls; no sharing is enabled.'}</p></section></div><div><section class="panel"><h2>Subscription</h2><div class="settingsrow"><div><strong>Free simulation access</strong><p>No paid subscription</p></div><span class="pill neutral">Free</span></div>${link('View subscription','profile/subscription','secondary full')}</section><section class="panel" style="margin-top:23px"><h2>Account</h2>${[['Security & password','Sessions and password recovery'],['Language & region','English (India) · INR'],['Sound & haptics','Contest alert preferences'],['Help & support','FAQs, contact and feedback']].map(([n,d])=>`<button class="account-row" data-sync="account-info" data-value="${n}"><span><strong>${n}</strong><small>${d}</small></span>${icon('arrow')}</button>`).join('')}${account?'<button class="ghost" data-action="logout">Sign out</button>':link('Leave demo','', 'ghost')}<button class="ghost negative" data-sync="account-info" data-value="Delete account">Delete account</button>${account?'':'<button class="ghost" data-action="reset">Reset local demo</button>'}</section><section class="panel" style="margin-top:23px"><h2>Personal details</h2><form id="profileform" class="profileform" style="margin-top:20px"><label class="field">Display name<input name="name" value="${esc(state.name)}" required maxlength="70"></label><label class="field">Weekly learning goal<select name="goal">${[35,75,105,210].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} minutes</option>`).join('')}</select></label><button class="primary">Save preferences</button></form></section></div></div>`)}

function allContests(){if(account)return [];return [...contests,...(state.customContests||[])];}
function selectedCompetition(){return allContests().find(c=>c.id===(state.portfolioContest||'nifty-sprint'))||contests[0];}
function fmt(n){return Number(n).toLocaleString('en-IN');}
function pct(n){return (n>=0?'+':'')+Number(n).toFixed(2)+'%';}
function progress(n,blue=false){return `<div class="progress ${blue?'blue':''}"><span style="width:${Math.max(0,Math.min(100,n))}%"></span></div>`;}
function fixtureNote(){return '<p class="small fixture-note">Reference demo · illustrative balances, results and rewards. No real trades, prizes, orders or subscriptions.</p>';}
function metric(label,value,cls=''){return `<div><span>${label}</span><strong class="${cls}">${value}</strong></div>`;}
function courseDone(c){return Math.min(c.lessons,c.done+(state.courseProgress?.[c.id]||0));}
function xpTotal(){return 4820+Object.values(state.courseProgress||{}).reduce((a,v)=>a+v*150,0);}
function coins(){return state.coins??12480;}
function badgeGrid(){return `<div class="badge-grid">${achievements.map(([n,d],i)=>`<div class="panel badge-item">${icon(i===0?'wallet':i===1?'clock':i===4?'users':'trophy')}<strong>${n}</strong><p>${d}</p></div>`).join('')}</div>`;}
function activeCards(){if(account)return `<section class="panel"><p>Your contest memberships are saved on the server.</p>${link("View My Contests →","my-contests")}</section>`;return `<div class="active-contest-grid">${allContests().filter(c=>state.joined.includes(c.id)).map(c=>`<article class="panel active-contest"><div class="row"><h3>${esc(c.name)}</h3><span class="pill neutral">${c.time}</span></div><div class="contest-metrics">${metric('Rank','#'+fmt(c.rank)+' / '+fmt(c.count))}${metric('P&L',pct(c.ret),c.ret>=0?'positive':'negative')}</div><div class="row small"><span>Contest progress</span><span>${c.progress}%</span></div>${progress(c.progress)}<button class="ghost full" data-sync="select-contest" data-id="${c.id}">Continue contest →</button></article>`).join('')}</div>`;}


function legal(kind){return `${nav()}<main class="onboardwrap"><section class="panel lessonbody"><h1 style="font-size:30px">${kind==='privacy'?'Development privacy information':'Development terms'}</h1>${kind==='privacy'?'<p>Creating an account sends your email, display name and password to the InvestIQ backend. Passwords are stored as secure hashes. Your profile, completed onboarding answers, preferences and privacy choices are stored with your account.</p><p>An HttpOnly cookie keeps you signed in. Session credentials and recovery links are not stored in browser localStorage. Guest practice activity is stored separately in this browser and is never uploaded as real account activity.</p><p>Verification and password recovery use email. In the local development setup, those messages are captured in a local inbox. Google Fonts is loaded for typography. Market data uses the configured synthetic or Yahoo end-of-day source; payments and real reward fulfillment are not available. The performance coach uses the configured backend AI provider: Ollama locally during development, or Gemini if enabled by the operator. The model receives your simulation observations and approved lesson excerpts; it receives no account email or private reflections. Ask Martin also sends your question and bounded conversation context to that provider. Martin questions, cited evidence and replies are saved privately; delete a conversation from its Chat history to remove them.</p><p>You can sign out and revoke sessions in Settings. Your public-profile preference controls display names on visible contest leaderboards and community content. Public community posts, replies, group memberships (as counts), poll totals and reactions (as counts) can be viewed by other people. Saved-post lists and individual votes remain private. Administrators can review reports and hidden content. Portfolio holdings remain private. Account deletion is not yet enabled. Production privacy and retention policies must be established before a public launch.</p>':'<p>InvestIQ is an educational application in development. Accounts, profiles, contests, saved portfolios and simulated results use the backend. Contests use synthetic or Yahoo end-of-day prices, as labelled. Learning progress and quiz results are saved on your account. Virtual coin earnings and sandbox redemption history are saved. Community discussions, replies, polls and public groups are shared through the backend. Private performance-coach reports use saved simulation evidence and published lessons. Reflections are saved privately and are not sent to the model.</p><p>All capital is virtual. Prices, returns, rankings and results shown in previews are illustrative. The onboarding profile describes an educational starting point and is not a suitability review, investment recommendation or promise of returns.</p><p>No real trading, payments, reward orders, subscriptions or mentor bookings are available. Production terms must be established before a public launch.</p>'}${link('Return to InvestIQ','','secondary')}</section></main>`;}
function resetPassword(){const completing=linkToken?.route==='reset-password';return `${nav()}<main class="onboardwrap"><form id="resetform" class="panel profileform"><span class="eyebrow">Account recovery</span><h2>${completing?'Choose a new password':'Reset your password'}</h2><p>${completing?'Use between 12 and 128 characters. All existing sessions will be revoked.':'Enter your email to request a single-use recovery link.'}</p>${completing?'<label class="field">New password<input type="password" name="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label class="field">Confirm password<input type="password" name="confirm" autocomplete="new-password" minlength="12" maxlength="128" required></label>':'<label class="field">Email<input type="email" name="email" autocomplete="email" required></label>'}<button class="primary">${completing?'Change password':'Request reset link'}</button><p role="status" data-form-status>${esc(linkResult)}</p>${link('Back to login','login','ghost')}</form></main>`;}
function verifyEmail(){return `${nav()}<main class="onboardwrap"><form id="verifyform" class="panel profileform"><h2>Verify your email</h2><p>${esc(linkResult||'Confirm your email using the link in your inbox.')}</p>${linkToken?.route==='verify-email'?'<button class="primary">Verify email</button>':''}<p role="status" data-form-status></p>${link('Continue',account?'dashboard':'login','secondary')}</form></main>`;}
function notFound(){return `${nav()}<main class="onboardwrap panel empty"><h2>This page isn’t here.</h2><p style="margin:18px 0">Let’s return to your workspace.</p>${link('Go to dashboard','dashboard')}</main>`}
function current(){return location.hash.split('?')[0].replace(/^#\/?/,'').replace(/\/$/,'')||''}
function render(){if(isAdminPortal&&!account&&!['login','verify-email','reset-password'].includes(current()))history.replaceState(null,'',location.pathname+location.search+'#/login');if(account?.role==='admin'&&!/^(contests\/(admin|create-platform|[0-9a-f-]{36})|admin\/courses(?:\/(?:new|[0-9a-f-]{36}))?|verify-email|reset-password)$/.test(current()))history.replaceState(null,'',location.pathname+location.search+'#/contests/admin');modal=null;const raw=current(),parts=raw.split('/'),aliases={home:'dashboard',build:'portfolio',learn:'academy',community:'social',rewards:'marketplace'};const base=aliases[parts[0]]||parts[0],id=parts[1],r=[base,id].filter(Boolean).join('/');let html=base==='admin'?serverAdmin.page():base===''?landing():base==='login'?auth():base==='signup'?auth(true):base==='onboarding'?onboard():base==='dashboard'?dashboard():base==='contests'?contestPage(id):base==='portfolio'?portfolio(id):base==='academy'?academy(id):base==='insights'?insights():base==='marketplace'?marketplace(id):base==='social'?social():base==='profile'?profile(id):base==='settings'?settings():base==='my-contests'?myContests():base==='leaderboard'?leaderboardPage(id):base==='performance'||base==='contest-history'?serverPerformance.page():base==='privacy'||base==='terms'?legal(base):base==='reset-password'?resetPassword():base==='verify-email'?verifyEmail():notFound();app.innerHTML=html;document.title=(isAdminPortal||account?.role==='admin'?'Administration':navitems.find(x=>x[0]===base)?.[2]||'Learn. Practice. Grow.')+' — InvestIQ';if(base==='portfolio'&&(account||id))serverPortfolio.ensure();else{serverPortfolio.deactivate();if(base==='portfolio'){updateAllocation();ensureMarketData();}}if(['contests','my-contests'].includes(base))serverContests.ensure();else serverContests.deactivate();if(['leaderboard','performance','contest-history'].includes(base)||(base==='dashboard'&&account))serverPerformance.ensure();else serverPerformance.deactivate();if(base==='academy')serverLearning.ensure();else serverLearning.deactivate();if(base==='insights')serverCoach.ensure();else serverCoach.deactivate();if(base==='social')serverCommunity.ensure();else serverCommunity.deactivate();if(base==='marketplace')serverRewards.ensure();else serverRewards.deactivate();if(base==='admin')serverAdmin.ensure();else serverAdmin.deactivate();martin.sync();document.dispatchEvent(new CustomEvent('investiq:render'));}
function dialog(title,body,action){modal=document.createElement('div');modal.className='dialogback';modal.innerHTML=`<section class="panel dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="row"><h2 id="dialog-title">${title}</h2><button class="ghost" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div>${body}<div class="row"><button class="secondary" data-action="close-dialog">Cancel</button>${action}</div></section>`;app.append(modal);modal.querySelector('button').focus();}
function updateAllocation(){const total=allocationTotal(),c=selectedCompetition();const status=document.getElementById('allocationstatus');if(status){status.textContent=total.toFixed(1)+'% allocated · max 25% per holding';status.className=Math.abs(total-100)<.02?'positive':'subtle';}const value=document.getElementById('deployed-value');if(value)value.textContent=money(total/100*c.capital)+' / '+money(c.capital);const bar=document.getElementById('deployed-bar');if(bar)bar.style.width=Math.min(100,total)+'%';}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;if(['logout','request-verification','retry-onboarding','revoke-session','request-recovery'].includes(a)){e.preventDefault();await identityAction(a,id,b);return;}if(a==='reload-market'){await refreshMarket();return;}if(a==='market-more'){await loadMarketPage(true);return;}if(a==='answer'){state.answers[step]=Number(b.dataset.index);save();render()}else if(a==='back'){step=Math.max(0,step-1);render()}else if(a==='next'){await advanceOnboarding(b)}else if(a==='retake'){step=0;if(current()==='onboarding')render();else location.hash='/onboarding'}else if(a==='contest-filter'){filter=b.dataset.value;render()}else if(a==='join'){if(!state.joined.includes(id)){state.joined.push(id);save();toast('You joined the practice contest. Build your portfolio next.')}location.hash='/portfolio'}else if(a==='sector'){sector=b.dataset.value;await loadMarketPage();}else if(a==='add-stock'){if(!stocks.find(x=>x.id===id)?.usable||!marketSnapshotReady()){toast('A current, eligible quote is required. Refresh market data.');return;}if(!(id in state.allocations)){state.allocations[id]=0;save();render();toast('Company added. Set its allocation.')}}else if(a==='remove-stock'){delete state.allocations[id];save();render()}else if(a==='submit-portfolio'){if(!marketSelectionReady()){toast('Refresh missing or stale quotes before reviewing.');return;}const vals=Object.values(state.allocations),total=allocationTotal();if(total!==100){toast('Your allocations must total exactly 100%.');return}if(vals.filter(v=>v>0).length<3){toast('Choose at least 3 companies with a positive allocation.');return}if(vals.some(v=>v>40)){toast('Keep every holding at or below 40% for this practice portfolio.');return}dialog('Review your allocation',`<p>Your ₹1,00,000 virtual portfolio is ready.</p><div>${Object.entries(state.allocations).filter(([,v])=>v>0).map(([k,v])=>`<div class="settingsrow"><strong>${k}</strong><span>${v}% · ${money(v*1000)}</span></div>`).join('')}</div><p class="small">This saves a local practice submission. No orders are placed.</p>`,`<button class="primary" data-action="confirm-portfolio">Confirm practice submission</button>`)}else if(a==='confirm-portfolio'){state.savedPortfolio={allocations:{...state.allocations},at:new Date().toISOString()};save();render();toast('Practice portfolio saved successfully.')}else if(a==='close-dialog'){modal?.remove();modal=null}else if(a==='quiz'){lessonAnswer=Number(b.dataset.index);render()}else if(a==='complete'){const c=courses.find(x=>x.id===id);if(!c||lessonAnswer!==c.correct)return;if(!state.completed.includes(id)){state.completed.push(id);state.courseProgress=state.courseProgress||{};state.courseProgress[id]=(state.courseProgress[id]||0)+1;}save();toast('Lesson complete. Your learning score has grown.');render()}else if(a==='interest'){state.interests=state.interests||[];if(!state.interests.includes(id))state.interests.push(id);save();render();toast('Interest saved locally. No email is sent.')}else if(a==='like'){state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];save();render()}else if(a==='delete-post'){state.posts=state.posts.filter(x=>x.id!==id);save();render()}else if(a==='reminders'){state.reminders=!state.reminders;save();render()}else if(a==='reset'){dialog('Reset your demo?', '<p>This clears the learning progress, reflections, onboarding answers, and portfolio saved in this browser.</p>','<button class="primary" data-action="confirm-reset">Reset browser demo</button>')}else if(a==='confirm-reset'){state=JSON.parse(JSON.stringify(defaults));step=0;save();render();toast('Demo reset.')}else if(a==='notifications'){const existing=document.getElementById('notifications');if(existing){existing.remove();return}const panel=document.createElement('section');panel.id='notifications';panel.className='panel notificationpanel';panel.innerHTML='<h3>Your learning updates</h3><div class="callout"><strong>Ready for your next lesson?</strong><p>Your foundation learning path is available in the academy.</p></div><div class="callout"><strong>Practice at your own pace</strong><p>Join a starter league when you’re ready.</p></div>';app.querySelector('.workspace').append(panel)}});
app.addEventListener('input',e=>{const t=e.target;if(t.dataset.alloc){let n=Number(t.value);if(!Number.isFinite(n))n=0;n=Math.max(0,Math.min(100,n));state.allocations[t.dataset.alloc]=n;app.querySelectorAll('[data-alloc="'+t.dataset.alloc+'"]').forEach(x=>{if(x!==t)x.value=n});save();updateAllocation()}else if(t.id==='stocksearch'){stockQuery=t.value;clearTimeout(marketSearchTimer);marketSearchTimer=setTimeout(()=>loadMarketPage(),200)}else if(t.id==='global-search'){let q=t.value.trim().toLowerCase(),box=document.getElementById('searchresults');box.hidden=!q;if(q){const list=navitems.filter(x=>x[2].toLowerCase().includes(q));const matches=courses.filter(x=>x.title.toLowerCase().includes(q));box.innerHTML=list.map(([r,i,n])=>`<a href="#/${r}">${icon(i)}${n}</a>`).join('')+matches.map(c=>`<a href="#/academy">${icon('book')}${c.title}</a>`).join('')||'<p class="small" style="padding:10px">No matching pages or lessons.</p>'}}});
app.addEventListener('change',e=>{if(e.target.dataset.task!==undefined){const i=Number(e.target.dataset.task);state.tasks=e.target.checked?[...new Set([...state.tasks,i])]:state.tasks.filter(x=>x!==i);save();render()}});
app.addEventListener('submit',async e=>{
  const f=e.target;
  if(!['authform','profileform','journalform','postform','resetform','verifyform'].includes(f.id))return;
  e.preventDefault();
  const data=new FormData(f);
  await runForm(f,async()=>{
    if(f.id==='authform'){
      const input={email:String(data.get('email')),password:String(data.get('password'))};
      const user=f.dataset.kind==='signup'?await authApi.register({...input,name:String(data.get('name'))}):await authApi.login(input);
      if(isAdminPortal&&user.role!=='admin'){await authApi.logout();throw new Error('Administrator access is required. Sign in with your admin account.');}
      applyAccount(user); f.reset();
      try{if(account.role!=='admin')await loadQuestions();}catch{toast('Signed in. Please retry loading onboarding.');}
      step=0;location.hash=account.role==='admin'?'/contests/admin':account.onboarding?'/dashboard':'/onboarding';render();
    }else if(f.id==='profileform'){
      if(account){applyAccount(await profileApi.update({name:String(data.get('name')),weekly_goal:Number(data.get('goal'))}));}
      else{state.name=String(data.get('name')).trim()||'InvestIQ Learner';state.goal=Number(data.get('goal'));save();}
      render();toast('Profile saved.');
    }else if(f.id==='resetform'){
      if(linkToken?.route==='reset-password'){
        if(data.get('password')!==data.get('confirm'))throw new Error('Passwords do not match.');
        const result=await authApi.completePasswordReset({token:linkToken.token,password:String(data.get('password'))});
        linkToken=null;leaveAccount();linkResult=result.message;location.hash='/login';render();toast(result.message);
      }else{
        const result=await authApi.requestPasswordReset(String(data.get('email')));
        f.querySelector('[data-form-status]').textContent=result.message;
      }
    }else if(f.id==='verifyform'){
      if(!linkToken)throw new Error('Open the verification link from your inbox.');
      const result=await authApi.completeVerification(linkToken.token);linkToken=null;linkResult=result.message;
      if(account)applyAccount(await profileApi.get());render();toast(result.message);
    }else if(f.id==='journalform'){state.journal=String(data.get('journal'));save();toast(account?'Reflection kept in this preview session.':'Reflection saved in this browser.');}
    else if(f.id==='postform'){
      const text=String(data.get('post')).trim();if(text.length<5)throw new Error('Write at least 5 characters.');
      state.posts.unshift({id:'post-'+Date.now(),name:state.name,initials:initials(),tag:'Market Discussion',text,likes:0,comments:0,own:true});save();render();toast('Reflection saved in the practice preview.');
    }
  });
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal.remove();modal=null}if(e.key==='Tab'&&modal){const nodes=[...modal.querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
window.addEventListener('hashchange',()=>{consumeLink();lessonAnswer=null;render();window.scrollTo(0,0)});bootIdentity();

app.addEventListener('click',e=>{const button=e.target.closest('[data-password-toggle]');if(!button)return;const input=document.getElementById('auth-password');if(!input)return;const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'Hide password':'Show password');});

// Reference interactions are local-only and reuse the same state across pages.
app.addEventListener('click',async e=>{const b=e.target.closest('[data-sync]');if(!b||b.disabled)return;const {sync:a,id,value}=b.dataset;
if(a==='select-contest'){selectedContest=id;if(current()==='my-contests')render();else location.hash='/my-contests';}
else if(a==='build-for'){state.portfolioContest=id;save();if(current()==='portfolio')render();else location.hash='/portfolio';}
else if(a==='cap-filter'){capFilter=value;render();await loadMarketPage();}
else if(a==='portfolio-mode'){portfolioMode=value;render();}
else if(a==='reward-filter'){rewardFilter=value;render();}
else if(a==='reward-sort'){rewardSort=value;render();}
else if(a==='community-filter'){communityFilter=value;render();}
else if(a==='rank-filter'){rankFilter=value;render();}
else if(a==='new-post'){document.getElementById('community-composer')?.focus();}
else if(a==='vote'){state.pollVote=value;save();render();}
else if(a==='save-post'){state.savedPosts=state.savedPosts||[];state.savedPosts=state.savedPosts.includes(id)?state.savedPosts.filter(x=>x!==id):[...state.savedPosts,id];save();render();}
else if(a==='join-community'){state.communities=state.communities||[];state.communities=state.communities.includes(value)?state.communities.filter(x=>x!==value):[...state.communities,value];save();render();}
else if(a==='share'){dialog('Share '+esc(value),'<p>Share controls are shown as a local preview. This prototype does not publish your profile, report or posts.</p>','<button class="primary" data-action="close-dialog">Done</button>');}
else if(a==='comments'){dialog('Discussion replies','<p>Replies are a preview in this frontend. No comments are sent to the reference application.</p>','<button class="primary" data-action="close-dialog">Done</button>');}
else if(a==='earn'){document.getElementById('earn-section')?.scrollIntoView({behavior:'smooth',block:'start'});}
else if(a==='preference'){if(account){b.disabled=true;try{const body={[id]:!(state.preferences?.[id]??(b.dataset.default==='true'))};if(['public','holdings'].includes(id))await profileApi.updatePrivacy(body);else await profileApi.updatePreferences(body);applyAccount(await profileApi.get());render();toast('Preference saved.');}catch(error){toast(error.message);b.disabled=false;}return;}state.preferences=state.preferences||{};state.preferences[id]=!(state.preferences[id]??(b.dataset.default==='true'));save();render();}
else if(a==='account-info'){if(account&&value==='Security & password'){try{await openSessions();}catch(error){toast(error.message);}return;}dialog(esc(value),'<p>This account control is a UI preview. Connect your backend before enabling account, billing or security operations.</p>','<button class="primary" data-action="close-dialog">Done</button>');}
else if(a==='review-portfolio'){if(!marketSelectionReady()){toast('Refresh missing or stale quotes before reviewing.');return;}const c=selectedCompetition(),entries=Object.entries(state.allocations).filter(([,v])=>Number(v)>0),total=allocationTotal();if(entries.length<5||entries.length>12){toast('Choose 5 to 12 holdings with positive weights.');return;}if(Object.values(state.allocations).some(v=>!Number.isFinite(Number(v))||Number(v)>25||Number(v)<0)){toast('Keep every holding at or below 25%.');return;}if(total>100.02||total<99.5){toast('Allocate 100% of capital before submitting. Quantity mode permits up to 0.5% unspent for rounding.');return;}dialog('Review & submit',`<p>${esc(c.name)} · ${money(c.capital)} virtual capital</p>${entries.map(([id,v])=>`<div class="settingsrow"><strong>${id}</strong><span>${Number(v).toFixed(2)}% · ${money(c.capital*Number(v)/100)}</span></div>`).join('')}<p class="small">Local practice submission. No real orders or contest entry is transmitted.</p>`,'<button class="primary" data-action="confirm-portfolio">Confirm practice submission</button>');}
else if(a==='redeem'){const r=rewardCatalog.find(x=>x.id===id);if(!r||coins()<r.cost)return;dialog('Preview reward redemption',`<p>${esc(r.name)} · ${fmt(r.cost)} coins</p><p>This deducts demo coins and adds a local history entry. No real gift card, shipment, booking or purchase is created.</p>`,`<button class="primary" data-sync="confirm-redeem" data-id="${r.id}">Confirm local preview</button>`);}
else if(a==='confirm-redeem'){const r=rewardCatalog.find(x=>x.id===id);if(!r||coins()<r.cost)return;state.coins=coins()-r.cost;state.redemptions=[{name:r.name,date:new Date().toLocaleDateString('en-IN'),cost:r.cost,status:'Demo only'},...(state.redemptions||[])];save();render();toast('Demo redemption saved. No real reward is ordered.');}
});
app.addEventListener('change',async e=>{const t=e.target;if(t.id==='sector-select'){sector=t.value;await loadMarketPage();}else if(t.id==='contest-query'){contestQuery=t.value;render();}else if(t.dataset.quantity){const stock=stocks.find(s=>s.id===t.dataset.quantity);if(!stock?.usable||!marketSnapshotReady()){toast('This quantity preview requires a current quote.');return;}const qty=Math.max(0,Math.floor(Number(t.value)||0));state.allocations[stock.id]=Number((qty*stock.price/selectedCompetition().capital*100).toFixed(4));save();updateAllocation();}});

// Real identity is loaded from cookies and never serialized into the demo store.
function applyAccount(user){
  if(!account){demoSnapshot=structuredClone(state);state={...structuredClone(defaults),name:'',answers:[],joined:[],allocations:{},completed:[],posts:[],tasks:[],coins:0,redemptions:[],journal:''};}
  if(account?.id!==user.id){serverAdmin.reset();serverContests.reset();serverPortfolio.reset();serverPerformance.reset();serverLearning.reset();serverRewards.reset();serverCommunity.reset();serverCoach.reset();martin.reset();}
  account=user;state.name=user.name;state.goal=user.weekly_goal;
  state.preferences={...user.preferences,...user.privacy};
  state.onboard=Boolean(user.onboarding);
  state.experience=user.onboarding?.experience||'beginner';
  state.profile=user.onboarding?.learning_profile||'Foundation Explorer';
  state.answers=questionVersion&&user.onboarding?.version===questionVersion?questions.map(q=>q.optionIds.indexOf(user.onboarding.answers[q.id])):[];
}
function leaveAccount(){serverAdmin.reset();serverContests.reset();serverPortfolio.reset();serverPerformance.reset();serverLearning.reset();serverRewards.reset();serverCommunity.reset();serverCoach.reset();martin.reset();account=null;questions=demoQuestions;questionVersion=null;state=demoSnapshot||structuredClone(defaults);demoSnapshot=null;step=0;}
async function loadQuestions(){
  const result=await profileApi.onboardingQuestions();
  questions=result.questions.map(q=>({id:q.id,tag:q.tag,title:q.title,desc:q.description,opts:q.options.map(o=>[o.title,o.description]),optionIds:q.options.map(o=>o.id)}));
  questionVersion=result.version;if(account)applyAccount(account);
}
function consumeLink(){
  const hash=location.hash.slice(2),[route,query]=hash.split('?');
  if(['reset-password','verify-email'].includes(route)&&query){
    const token=new URLSearchParams(query).get('token');
    if(token&&token.length<=128){linkToken={route,token};linkResult='';}
    history.replaceState(null,'',location.pathname+location.search+'#/'+route);
  }
}
async function bootIdentity(){
  consumeLink();app.innerHTML='<main class="onboardwrap panel" role="status">Loading your account…</main>';
  try{const user=await profileApi.get();if(isAdminPortal&&user.role!=='admin'){await authApi.logout();toast('Sign in with an administrator account.');}else{applyAccount(user);if(account.role!=='admin')await loadQuestions();}}
  catch(error){if(error.status!==401)toast('Account service unavailable. Practice previews are still available.');}
  render();
}
async function runForm(form,task){
  if(form.dataset.pending==='true')return;
  form.dataset.pending='true';const buttons=[...form.querySelectorAll('button[type="submit"],button:not([type])')];buttons.forEach(b=>b.disabled=true);
  let status=form.querySelector('[data-form-status]');if(!status){status=document.createElement('p');status.dataset.formStatus='';status.setAttribute('role','status');form.append(status);}status.textContent='Saving…';
  try{await task();if(status.isConnected&&status.textContent==='Saving…')status.textContent='Saved.';}
  catch(error){status.textContent=error.status===422?'Check your details. New passwords need 12–128 characters.':error.message||'Unable to connect. Please try again.';}
  finally{form.dataset.pending='false';buttons.forEach(b=>b.disabled=false);}
}
async function advanceOnboarding(button){
  if(identityBusy||state.answers[step]===undefined)return;
  if(!account){step++;if(step===5){state.onboard=true;state.experience=state.answers[0]<2?'beginner':state.answers[0]===2?'intermediate':'advanced';state.profile=state.experience==='beginner'?'Foundation Explorer':state.experience==='intermediate'?'Confident Builder':'Strategy Explorer';state.goal=[35,105,210,75][state.answers[4]];save();}render();return;}
  if(step<questions.length-1){step++;render();return;}
  identityBusy=true;button.disabled=true;
  try{const answers=Object.fromEntries(questions.map((q,i)=>[q.id,q.optionIds[state.answers[i]]]));applyAccount(await profileApi.saveOnboarding({version:questionVersion,answers}));step=questions.length;render();}
  catch(error){toast(error.message);button.disabled=false;}
  finally{identityBusy=false;}
}
async function openSessions(){
  const sessions=await authApi.sessions();
  dialog('Sessions and password',sessions.map(s=>`<div class="settingsrow"><div><strong>${s.current?'This session':'Another session'}</strong><p>Started ${esc(new Date(s.created_at).toLocaleString())}</p></div><button class="secondary" data-action="revoke-session" data-id="${s.id}">Revoke${s.current?' and sign out':''}</button></div>`).join('')+'<p>Password recovery revokes all sessions.</p>','<button class="primary" data-action="request-recovery">Email password reset link</button>');
}
async function identityAction(action,id,button){
  if(identityBusy)return;identityBusy=true;button.disabled=true;
  try{
    if(action==='logout'){await authApi.logout();leaveAccount();location.hash='/login';render();}
    else if(action==='request-verification'){const result=await authApi.requestVerification(account.email);toast(result.message);}
    else if(action==='request-recovery'){const result=await authApi.requestPasswordReset(account.email);toast(result.message);}
    else if(action==='retry-onboarding'){await loadQuestions();render();}
    else if(action==='revoke-session'){
      const sessions=await authApi.sessions(),currentSession=sessions.find(s=>s.id===id)?.current;
      await authApi.revokeSession(id);
      if(currentSession){leaveAccount();location.hash='/login';render();}else{modal?.remove();await openSessions();}
    }
  }catch(error){toast(error.message);button.disabled=false;}
  finally{identityBusy=false;if(button.isConnected)button.disabled=false;}
}

window.addEventListener('investiq:session-expired',()=>{if(account){leaveAccount();location.hash='/login';render();toast('Your session changed or expired. Sign in again.');}});
window.addEventListener('investiq:csrf-changed',()=>{if(account){bootIdentity();toast('Your session changed. Review the refreshed profile before retrying.');}});

// Market prices come from the backend. No browser-fixture fallback is used on failure.
function formatMarketPrice(value){
  if(value===null||value===undefined)return 'Unavailable';
  const [whole,fraction='']=String(value).split('.');
  return '₹'+BigInt(whole).toLocaleString('en-IN')+'.'+fraction.replace(/0+$/,'').padEnd(2,'0');
}
function marketMore(){return marketState.nextCursor&&!marketState.error&&!marketState.pageError?`<button class="secondary full" data-action="market-more" ${marketState.pageLoading?'disabled':''}>Load more instruments</button>`:'';}
function marketNotice(){
  const meta=marketState.metadata,first=meta?.items.find(x=>x.observed_at);
  const stamp=value=>new Date(value).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'});
  return `<div class="callout" id="market-status" role="status"><strong>${meta?.data_kind==='yahoo'?'Yahoo Finance EOD market data':'Synthetic EOD market data'}</strong><p>${meta?'Expected session '+esc(meta.expected_session_date)+' · '+(first?'Observed '+esc(stamp(first.observed_at))+' IST.':'No observed prices are available.'):'Loading source and session information.'}</p>${first?`<p class="small">Source ${esc(first.source)} · ${esc(first.dataset_version)} · ingested ${esc(stamp(first.ingested_at))} IST.</p>`:''}<p>${meta?.data_kind==='yahoo'?'Daily market prices for educational virtual portfolios. This is not a live trading feed.':'Illustrative prices for development. These are not real historical or live quotes.'}${meta&&!meta.all_current?' Some quotes are stale or missing; affected instruments are disabled.':''}</p>${meta?`<p class="small">Freshness evaluated at ${esc(stamp(meta.as_of))} IST. Refresh before using an older preview.</p>`:''}<button class="ghost" data-action="reload-market" ${marketState.loading?'disabled':''}>Refresh market data</button></div>`;
}
function marketSnapshotReady(){return marketState.loaded&&!marketState.loading&&!marketState.error&&Date.now()-marketState.loadedAt<=60000;}
function marketSelectionReady(){return marketSnapshotReady()&&Object.keys(state.allocations).every(id=>stocks.find(x=>x.id===id)?.usable);}
function ensureMarketData(){if(!marketState.loading&&(!marketState.loaded||Date.now()-marketState.loadedAt>60000))refreshMarket();}
async function refreshMarket(){
  if(marketState.loading)return;
  marketState.loading=true;marketState.error='';marketState.pageError='';marketPageSequence++;
  if(['portfolio','build'].includes(current()))render();
  try{
    const [sectorsDoc,first]=await Promise.all([marketApi.sectors(),marketApi.instruments({limit:100})]);
    const catalogue=[...first.items];let cursor=first.next_cursor;
    while(cursor){const page=await marketApi.instruments({limit:100,cursor});catalogue.push(...page.items);cursor=page.next_cursor;}
    const quotes=[];let metadata=null;
    for(let i=0;i<catalogue.length;i+=100){const batch=await marketApi.quotes(catalogue.slice(i,i+100).map(x=>x.id),metadata?.as_of);metadata=metadata||batch;quotes.push(...batch.items);}
    if(!metadata)throw new Error('The instrument catalogue is empty.');
    metadata={...metadata,items:quotes,all_current:quotes.every(q=>q.eligible_for_simulation)};
    const byId=new Map(quotes.map(q=>[q.instrument_id,q]));
    stocks=catalogue.map(i=>{const q=byId.get(i.id);return {id:i.symbol,instrumentId:i.id,name:i.name,sector:i.sector?.name||'Benchmark',sectorId:i.sector?.id,cap:{large:'Large Cap',mid:'Mid Cap',small:'Small Cap'}[i.market_cap],price:q?.close??null,usable:Boolean(q?.eligible_for_simulation),quote:q};});
    marketState.sectors=sectorsDoc.items;marketState.metadata=metadata;marketState.loaded=true;
    await loadMarketPage();
  }catch(error){stocks=[];marketState.items=[];marketState.metadata=null;marketState.error=error.message||'Market data is unavailable. Please try again.';marketState.loaded=true;}
  finally{marketState.loading=false;marketState.loadedAt=Date.now();if(['portfolio','build'].includes(current()))render();}
}
async function loadMarketPage(append=false){
  if(!marketState.loaded||marketState.error)return;
  const sequence=++marketPageSequence;marketState.pageLoading=true;marketState.pageError='';updateMarketRows();
  try{
    const params={limit:8,query:stockQuery,sort:'symbol'};
    if(sector!=='All')params.sector=sector;
    if(capFilter!=='All')params.market_cap=capFilter.split(' ')[0].toLowerCase();
    if(append&&marketState.nextCursor)params.cursor=marketState.nextCursor;
    const page=await marketApi.instruments(params);
    if(sequence!==marketPageSequence)return;
    const rows=page.items.map(i=>stocks.find(s=>s.instrumentId===i.id)).filter(Boolean);
    marketState.items=append?[...marketState.items,...rows]:rows;marketState.nextCursor=page.next_cursor;
  }catch(error){if(sequence===marketPageSequence){marketState.pageError=error.message||'Instrument search failed.';marketState.items=[];marketState.nextCursor=null;}}
  finally{if(sequence===marketPageSequence){marketState.pageLoading=false;updateMarketRows();}}
}
function updateMarketRows(){const rows=document.getElementById('stockrows'),more=document.getElementById('market-more');if(rows)rows.innerHTML=stockRows();if(more)more.innerHTML=marketMore();}
